/* @lc app=leetcode id=2069 lang=kotlin */ class Robot(val w: Int, val h: Int, val st: IntArray = IntArray(2)) { fun step(num: Int) = (st[0] + num).let { st[0] = it % (2 * (w + h) - 4) }.let { st[1] = 1 } fun getPos(): IntArray = st[0].let { p -> if (p < w - 1) intArrayOf(p, 0) else if (p < w + h - 2) intArrayOf(w - 1, p - (w - 1)) else if (p < 2 * w + h - 3) intArrayOf(w - 1 - (p - (w + h - 2)), h - 1) else intArrayOf(0, h - 1 - (p - (2 * w + h - 3))) } fun getDir(): String = st[0].let { p -> if (p == 0) (if (st[1] == 0) "East" else "South") else if (p <= w - 1) "East" else if (p <= w + h - 2) "North" else if (p <= 2 * w + h - 3) "West" else "South" } }